CREATE TABLE odatano_cardano_NetworkInformation ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, network NVARCHAR(10) NOT NULL, maxSupply DECIMAL(20, 0), totalSupply DECIMAL(20, 0), circulatingSupply DECIMAL(20, 0), lockedSupply DECIMAL(20, 0), treasurySupply DECIMAL(20, 0), reservesSupply DECIMAL(20, 0), liveStake DECIMAL(20, 0), activeStake DECIMAL(20, 0), PRIMARY KEY(validFrom, network) );
CREATE TABLE odatano_cardano_Blocks ( hash NVARCHAR(64) NOT NULL, time NVARCHAR(255), height INTEGER, slotLeader NVARCHAR(255), epochNumber INTEGER, epochSlot INTEGER, size INTEGER, txCount INTEGER, fees DECIMAL(20, 0), PRIMARY KEY(hash) );
CREATE TABLE odatano_cardano_Epochs ( epoch INTEGER NOT NULL, startTime BIGINT, endTime BIGINT, firstBlockTime BIGINT, lastBlockTime BIGINT, blockCount INTEGER, txCount INTEGER, output NVARCHAR(255), fees DECIMAL(20, 0), activeStake DECIMAL(20, 0), PRIMARY KEY(epoch) );
CREATE TABLE odatano_cardano_Pools ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, poolId NVARCHAR(120) NOT NULL, vrfKeyHash NVARCHAR(255), blocksMinted INTEGER, blocksEpoch INTEGER, liveStake DECIMAL(20, 0), liveSize DECIMAL(5, 4), liveSaturation DECIMAL(5, 4), liveDelegators INTEGER, activeStake DECIMAL(20, 0), activeSize DECIMAL(5, 4), pledge DECIMAL(20, 0), margin DECIMAL(5, 4), fixedCost DECIMAL(20, 0), rewardAccount NVARCHAR(255), PRIMARY KEY(validFrom, poolId) );
CREATE TABLE odatano_cardano_Dreps ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, drepId NVARCHAR(120) NOT NULL, hex NVARCHAR(255), amount DECIMAL(20, 0), hasScript BOOLEAN, lastActiveEpoch INTEGER, retired BOOLEAN, expired BOOLEAN, PRIMARY KEY(validFrom, drepId) );
CREATE TABLE odatano_cardano_Assets ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, unit NVARCHAR(120) NOT NULL, policyId NVARCHAR(56), assetNameHex NVARCHAR(64), assetName NVARCHAR(128), fingerprint NVARCHAR(44), totalSupply NVARCHAR(40), mintOrBurnCount INTEGER, initialMintTxHash NVARCHAR(64), initialMintTime BIGINT, onchainMetadata NCLOB, registryName NVARCHAR(128), registryTicker NVARCHAR(16), registryDecimals INTEGER, registryDescription NCLOB, registryUrl NVARCHAR(256), registryLogo NCLOB, PRIMARY KEY(validFrom, unit) );
CREATE TABLE odatano_cardano_AssetHistory ( unit NVARCHAR(120) NOT NULL, txHash NVARCHAR(64) NOT NULL, "action" NVARCHAR(10), quantity NVARCHAR(40), blockTime BIGINT, blockHeight INTEGER, PRIMARY KEY(unit, txHash) );
CREATE TABLE odatano_cardano_Transactions ( hash NVARCHAR(64) NOT NULL, blockHash NVARCHAR(64), blockHeight INTEGER, blockTime BIGINT, slot BIGINT, txIndex INTEGER, fee DECIMAL(20, 0), deposit DECIMAL(20, 0), size INTEGER, hasMetadata BOOLEAN, hasInputs BOOLEAN, hasOutputs BOOLEAN, PRIMARY KEY(hash) );
CREATE TABLE odatano_cardano_TransactionMetadata ( id BIGINT NOT NULL, tx_hash NVARCHAR(64) NOT NULL, label NVARCHAR(20), payload NCLOB, PRIMARY KEY(id, tx_hash) );
CREATE TABLE odatano_cardano_TransactionInputs ( tx_hash NVARCHAR(64) NOT NULL, inputIndex INTEGER NOT NULL, address_address NVARCHAR(120), utxoData_dataHash NVARCHAR(64), utxoData_inlineDatum NCLOB, utxoData_referenceScriptHash NVARCHAR(64), isCollateral BOOLEAN, isReference BOOLEAN, hasAddresses BOOLEAN, hasAssets BOOLEAN, PRIMARY KEY(tx_hash, inputIndex) );
CREATE TABLE odatano_cardano_Addresses ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, address NVARCHAR(120) NOT NULL, stakeAddress NVARCHAR(120), type NVARCHAR(20), isScript BOOLEAN, totalLovelace DECIMAL(20, 0), utxoCount INTEGER, hasTransactions BOOLEAN, hasAssets BOOLEAN, hasUTxOs BOOLEAN, PRIMARY KEY(validFrom, address) );
CREATE TABLE odatano_cardano_AddressTransactions ( address_address NVARCHAR(120) NOT NULL, tx_hash NVARCHAR(64) NOT NULL, netAmount DECIMAL(20, 0), blockTime BIGINT, netAssets NCLOB, hasAssets BOOLEAN DEFAULT FALSE, PRIMARY KEY(address_address, tx_hash) );
CREATE TABLE odatano_cardano_AddressAssets ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, address_address NVARCHAR(120) NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(validFrom, address_address, unit) );
CREATE TABLE odatano_cardano_AddressUTxOs ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, address_address NVARCHAR(120) NOT NULL, hash NVARCHAR(64) NOT NULL, "index" INTEGER NOT NULL, blockHash NVARCHAR(64), utxodata_dataHash NVARCHAR(64), utxodata_inlineDatum NCLOB, utxodata_referenceScriptHash NVARCHAR(64), lovelace DECIMAL(20, 0), hasAssets BOOLEAN, PRIMARY KEY(validFrom, address_address, hash, "index") );
CREATE TABLE odatano_cardano_UTxOAssets ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, utxo_address_address NVARCHAR(120) NOT NULL, utxo_hash NVARCHAR(64) NOT NULL, utxo_index INTEGER NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(validFrom, utxo_address_address, utxo_hash, utxo_index, unit) );
CREATE TABLE odatano_cardano_TransactionInputAssets ( input_tx_hash NVARCHAR(64) NOT NULL, input_inputIndex INTEGER NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(input_tx_hash, input_inputIndex, unit) );
CREATE TABLE odatano_cardano_TransactionOutputs ( tx_hash NVARCHAR(64) NOT NULL, outputIndex INTEGER NOT NULL, address_address NVARCHAR(120), utxo_dataHash NVARCHAR(64), utxo_inlineDatum NCLOB, utxo_referenceScriptHash NVARCHAR(64), hasAddresses BOOLEAN, hasAssets BOOLEAN, PRIMARY KEY(tx_hash, outputIndex) );
CREATE TABLE odatano_cardano_TransactionOutputAssets ( output_tx_hash NVARCHAR(64) NOT NULL, output_outputIndex INTEGER NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(output_tx_hash, output_outputIndex, unit) );
CREATE TABLE odatano_cardano_Accounts ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, stakeAddress NVARCHAR(120) NOT NULL, active BOOLEAN, activeEpoch INTEGER, controlledAmount DECIMAL(20, 0), rewardsSum DECIMAL(20, 0), withdrawalsSum DECIMAL(20, 0), reservesSum DECIMAL(20, 0), treasurySum DECIMAL(20, 0), withdrawableAmount DECIMAL(20, 0), poolId_poolId NVARCHAR(120), drepId_drepId NVARCHAR(120), hasAddresses BOOLEAN, PRIMARY KEY(validFrom, stakeAddress) );
CREATE TABLE odatano_cardano_LedgerProtocolParameters ( network NVARCHAR(16) NOT NULL, epoch INTEGER NOT NULL, minFeeA INTEGER, minFeeB INTEGER, maxBlockSize INTEGER, maxTxSize INTEGER, maxBlockHeaderSize INTEGER, keyDeposit NVARCHAR(32), poolDeposit NVARCHAR(32), eMax INTEGER, nOpt INTEGER, a0 DECIMAL(18, 10), rho DECIMAL(18, 10), tau DECIMAL(18, 10), minPoolCost NVARCHAR(32), decentralisationParam DECIMAL(18, 10), extraEntropy NVARCHAR(128), protocolMajorVer INTEGER, protocolMinorVer INTEGER, minUtxo NVARCHAR(32), nonce NVARCHAR(128), costModels NCLOB, priceMem DECIMAL(18, 10), priceStep DECIMAL(18, 10), maxTxExMem NVARCHAR(32), maxTxExSteps NVARCHAR(32), maxBlockExMem NVARCHAR(32), maxBlockExSteps NVARCHAR(32), maxValSize NVARCHAR(32), collateralPercent INTEGER, maxCollateralInputs INTEGER, coinsPerUtxoSize NVARCHAR(32), coinsPerUtxoWord NVARCHAR(32), fetchedAt TIMESTAMP_TEXT, source NVARCHAR(32), PRIMARY KEY(network, epoch) );
CREATE TABLE odatano_cardano_TransactionBuilds ( validFrom TIMESTAMP_TEXT NOT NULL, validTo TIMESTAMP_TEXT, id NVARCHAR(36) NOT NULL, network NVARCHAR(10), builderEngine NVARCHAR(20), senderAddress NVARCHAR(120), changeAddress NVARCHAR(120), unsignedTxCbor NCLOB, txBodyHash NVARCHAR(64), fee DECIMAL(20, 0), size INTEGER, createdAt BIGINT, hasInputs BOOLEAN, hasOutputs BOOLEAN, wasSubmitted BOOLEAN, scriptHash NVARCHAR(56), mintScriptHash NVARCHAR(56), fingerprint NVARCHAR(44), scriptAddress NVARCHAR(120), forcedInputsUsed INTEGER, referenceInputsUsed INTEGER, collateralAvailable BOOLEAN, PRIMARY KEY(validFrom, id) );
CREATE TABLE odatano_cardano_TransactionBuildInputs ( build_id NVARCHAR(36) NOT NULL, inputIndex INTEGER NOT NULL, txHash NVARCHAR(64), outputIndex INTEGER, address NVARCHAR(120), lovelace DECIMAL(20, 0), hasAssets BOOLEAN, PRIMARY KEY(build_id, inputIndex) );
CREATE TABLE odatano_cardano_TransactionBuildInputAssets ( input_build_id NVARCHAR(36) NOT NULL, input_inputIndex INTEGER NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(input_build_id, input_inputIndex, unit) );
CREATE TABLE odatano_cardano_TransactionBuildOutputs ( build_id NVARCHAR(36) NOT NULL, outputIndex INTEGER NOT NULL, address NVARCHAR(120), lovelace DECIMAL(20, 0), isChange BOOLEAN, hasAssets BOOLEAN, PRIMARY KEY(build_id, outputIndex) );
CREATE TABLE odatano_cardano_TransactionBuildOutputAssets ( output_build_id NVARCHAR(36) NOT NULL, output_outputIndex INTEGER NOT NULL, unit NVARCHAR(120) NOT NULL, asset_quantity DECIMAL(20, 0), asset_policyId NVARCHAR(56), asset_assetNameHex NVARCHAR(5000), asset_assetName NVARCHAR(128), asset_fingerprint NVARCHAR(44), PRIMARY KEY(output_build_id, output_outputIndex, unit) );
CREATE TABLE odatano_cardano_TransactionSubmissions ( id NVARCHAR(36) NOT NULL, build_id NVARCHAR(36), signedTxCbor NCLOB, txHash NVARCHAR(64), submittedAt BIGINT, status NVARCHAR(20) DEFAULT 'pending', errorCode NVARCHAR(50), errorMessage NCLOB, retryCount INTEGER, hasErrors BOOLEAN, PRIMARY KEY(id) );
CREATE TABLE odatano_cardano_TransactionSubmissionErrors ( id NVARCHAR(36) NOT NULL, submission_id NVARCHAR(36), occurredAt BIGINT, errorType NVARCHAR(50), errorCode NVARCHAR(50), errorMessage NCLOB, errorDetails NCLOB, isRecoverable BOOLEAN, PRIMARY KEY(id) );
CREATE TABLE odatano_cardano_AddressTransactionBuilds ( address_address NVARCHAR(120) NOT NULL, txBuild_id NVARCHAR(36) NOT NULL, PRIMARY KEY(address_address, txBuild_id) );
CREATE TABLE odatano_cardano_SignatureVerifications ( id NVARCHAR(36) NOT NULL, signingRequest_id NVARCHAR(36), signedTxCbor NCLOB, isValid BOOLEAN, txBodyHash NVARCHAR(64), witnessCount INTEGER, signerKeyHashes NCLOB, errorMessage NCLOB, warnings NCLOB, verifiedAt TIMESTAMP_TEXT, PRIMARY KEY(id) );
CREATE TABLE odatano_cardano_SigningRequests ( id NVARCHAR(36) NOT NULL, build_id NVARCHAR(36), txBodyHash NVARCHAR(64), unsignedTxCbor NCLOB, network NVARCHAR(10), status NVARCHAR(20) DEFAULT 'pending', createdAt TIMESTAMP_TEXT, expiresAt TIMESTAMP_TEXT, signedAt TIMESTAMP_TEXT, submittedAt TIMESTAMP_TEXT, cardanoCliCommand NCLOB, cip30TxCbor NCLOB, signerType NVARCHAR(20), signerInfo NVARCHAR(100), hsmKeyId NVARCHAR(40), submission_id NVARCHAR(36), errorMessage NCLOB, PRIMARY KEY(id) );
CREATE TABLE odatano_cardano_AddressSigningRequests ( address_address NVARCHAR(120) NOT NULL, signingRequest_id NVARCHAR(36) NOT NULL, PRIMARY KEY(address_address, signingRequest_id) );
CREATE TABLE cds_outbox_Messages ( ID NVARCHAR(36) NOT NULL, timestamp TIMESTAMP_TEXT, target NVARCHAR(255), msg NCLOB, attempts INTEGER DEFAULT 0, "partition" INTEGER DEFAULT 0, lastError NCLOB, lastAttemptTimestamp TIMESTAMP_TEXT, status NVARCHAR(23), task NVARCHAR(255), appid NVARCHAR(255), PRIMARY KEY(ID) );
CREATE VIEW CardanoODataService_NetworkInformation AS SELECT NetworkInformation_0.validFrom, NetworkInformation_0.validTo, NetworkInformation_0.network, NetworkInformation_0.maxSupply, NetworkInformation_0.totalSupply, NetworkInformation_0.circulatingSupply, NetworkInformation_0.lockedSupply, NetworkInformation_0.treasurySupply, NetworkInformation_0.reservesSupply, NetworkInformation_0.liveStake, NetworkInformation_0.activeStake FROM odatano_cardano_NetworkInformation AS NetworkInformation_0 WHERE (NetworkInformation_0.validFrom < session_context( '$valid.to' ) AND NetworkInformation_0.validTo > session_context( '$valid.from' ));
